steps.command:
perl -e '
open(F,"<:raw","secrets.7z") or die;
seek(F,48,0); read(F,$d,133)==133 or die "read";
my $props=chr(0x5D).pack("V",4096).pack("Q<",166);
open(O,">:raw","/tmp/hdr.lzma"); print O $props,$d; close O;
print "wrote ", length($props)+length($d), " bytes\n";
' && xz --format=lzma -dc /tmp/hdr.lzma > /tmp/hdr.bin; echo "exit=$?"; ls -l /tmp/hdr.bin; od -A d -t x1z /tmp/hdr.bin

mkdir -p /tmp/perllib/Compress/Raw
cat > /tmp/perllib/Compress/Raw/Lzma.pm <<'EOF'
package Compress::Raw::Lzma;
use strict;
use Exporter 'import';
our @EXPORT_OK = qw(LZMA_STREAM_END LZMA_DICT_SIZE_MIN LZMA_OK);
use constant LZMA_STREAM_END => 1;
use constant LZMA_DICT_SIZE_MIN => 4096;
use constant LZMA_OK => 0;
sub new { die "stub Lzma decoder called\n"; }
1;
EOF
perl -MCompress::Raw::Zlib=crc32 -e '
my $orig; open(F,"<:raw","/app/secrets.7z") or die; local $/; $orig=<F>; close F;
my $hdr; open(H,"<:raw","/tmp/hdr.bin") or die; local $/; $hdr=<H>; close H;
my $data = substr($orig,32,16);
my $nho = 16; my $nhs = length($hdr); my $nhc = crc32($hdr);
my $tail = pack("Q<",$nho).pack("Q<",$nhs).pack("V",$nhc);
my $shc = crc32($tail);
my $out = substr($orig,0,6).substr($orig,6,2).pack("V",$shc).$tail.$data.$hdr;
open(O,">:raw","/tmp/deenc.7z"); print O $out; close O;
printf "hdrlen=%d nhc=%08x shc=%08x total=%d\n",$nhs,$nhc,$shc,length($out);
'
echo "--- run 7z2john ---"
PERL5LIB=/tmp/perllib perl john/run/7z2john.pl /tmp/deenc.7z > /tmp/hash.txt 2>/tmp/hash.err; echo "exit=$?"; head -5 /tmp/hash.err; echo "HASH:"; cat /tmp/hash.txt

cd /tmp
perl -MDigest::SHA=sha256 -e '
open(F,"<:raw","/app/secrets.7z") or die; seek(F,32,0); read(F,$ct,16)==16 or die; close F;
open(O,">:raw","/tmp/ct.bin"); print O $ct; close O;
my $pw="1998"; my $u=join("",map{chr($_)."\0"} unpack("C*",$pw));
my $rounds=1<<19; my $s=Digest::SHA->new(256);
for(my $i=0;$i<$rounds;$i++){ $s->add($u); $s->add(pack("Q<",$i)); }
my $key=$s->digest;
print unpack("H*",$key),"\n";
open(K,">","/tmp/key.hex"); print K unpack("H*",$key); close K;
' > /tmp/key.out
KEY=$(cat /tmp/key.hex); echo "key=$KEY"
openssl enc -aes-256-cbc -d -K "$KEY" -iv 7f2aeca3d70f5f1298c191ab0faf61fc -nopad -in /tmp/ct.bin -out /tmp/comp.bin; echo "dec exit=$?"
od -A d -t u1 /tmp/comp.bin
